using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// ── 1. Strongly-typed metadata ───────────────────────────────────
// GetTypeInfo<T>() returns JsonTypeInfo<T> directly — no cast needed.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();

Console.WriteLine($"Type handled : {personInfo.Type.Name}");
Console.WriteLine($"Kind         : {personInfo.Kind}");
Console.WriteLine($"Properties   : {string.Join(", ", personInfo.Properties.Select(p => p.Name))}");

var json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized   : {json}");

// ── 2. Probe without throwing ────────────────────────────────────
// TryGetTypeInfo returns false instead of throwing when metadata isn't available.
bool havePerson = options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? _);
bool haveStream = options.TryGetTypeInfo(typeof(Stream), out JsonTypeInfo? _);

Console.WriteLine();
Console.WriteLine($"Metadata for Person? {havePerson}");   // True
Console.WriteLine($"Metadata for Stream? {haveStream}");   // False (abstract, no contract)

// Also works with the generic overload for a typed probe
bool haveInt = options.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo);
Console.WriteLine($"Metadata for int?    {haveInt} → kind={intInfo?.Kind}");

record Person(string Name, int Age);
EOF

