bool haveUri    = options.TryGetTypeInfo<Uri>(out JsonTypeInfo<Uri>? _);

Console.WriteLine();
Console.WriteLine($"Metadata for Person? {havePerson}");  // True  – covered by context
Console.WriteLine($"Metadata for Uri?    {haveUri}");     // False – not in the context

